package build

import (
	"github.com/KogenAI/kogen-executor/core"
	"github.com/KogenAI/kogen-loop/provider"
	"os"
	"path/filepath"
)

// recordBlob stores precisely the bytes named by the existing digest convention.
func (r *Run) recordBlob(v any) *provider.Digest {
	d := provider.Fingerprint(v)
	if d == nil {
		return nil
	}
	var data []byte
	if s, ok := v.(string); ok {
		data = []byte(s)
	} else {
		data, _ = core.EncodeJSON(v)
	}
	dir := filepath.Join(r.Dir, "blobs")
	err := os.MkdirAll(dir, 0700)
	if err == nil {
		err = os.Chmod(dir, 0700)
	}
	if err == nil {
		var f *os.File
		f, err = os.OpenFile(filepath.Join(dir, d.SHA256), os.O_WRONLY|os.O_CREATE|os.O_EXCL, 0600)
		if os.IsExist(err) {
			err = nil
		} else if err == nil {
			_, err = f.Write(data)
			if closeErr := f.Close(); err == nil {
				err = closeErr
			}
		}
	}
	if err != nil {
		r.mu.Lock()
		if r.logErr == nil {
			r.logErr = err
		}
		r.mu.Unlock()
	}
	return d
}
func (r *Run) recordItems(items []any) []*provider.Digest {
	out := make([]*provider.Digest, 0, len(items))
	for _, it := range items {
		out = append(out, r.recordBlob(it))
	}
	return out
}

// Size attribution uses canonical item JSON bytes, separate from rendered transport bytes.
func contextKinds(items []any) map[string]int {
	out := map[string]int{}
	for _, it := range items {
		m, _ := it.(map[string]any)
		kind, _ := m["type"].(string)
		if kind == "" {
			kind, _ = m["role"].(string)
		}
		if kind == "" {
			kind = "unknown"
		}
		raw, _ := core.EncodeJSON(it)
		out[kind] += len(raw)
	}
	return out
}
func contextSpend(before, after, summary int, mandatory, optional []any) map[string]any {
	return map[string]any{"before_bytes": before, "after_bytes": after, "summary_bytes": summary, "mandatory_bytes_by_kind": contextKinds(mandatory), "optional_bytes_by_kind": contextKinds(optional)}
}

