package build

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"slices"
	"strings"
	"time"

	"github.com/KogenAI/kogen-coordinator/git"
	"github.com/KogenAI/kogen-coordinator/project"
	"github.com/KogenAI/kogen-executor/agent"
	"github.com/KogenAI/kogen-executor/core"
	"github.com/KogenAI/kogen-executor/executor"
	"github.com/KogenAI/kogen-loop/provider"
	"github.com/KogenAI/kogen-loop/sys"
	"github.com/KogenAI/kogen-loop/tools"
	"github.com/KogenAI/kogen-verification/verify"
)

// Input is one `kogen intent build <slug>`.
type Input struct {
	Deps
	// Project is a directory inside the project's repository.
	Project string
	Slug    string
	// Context is the optional diagnostic data of `--context <file>`, already read.
	Context *Diagnostic
}

// ResumeInput is one `kogen intent resume <build-id>`.
type ResumeInput struct {
	Deps
	Project string
	ID      string
}

// Attempt is a Build in progress: its checkpointed state and the environment it runs in. The
// exported methods are what an independent review needs (see Reviewer).
type Attempt struct {
	State

	s           *sys.Session
	blockerNote string // invalid external blocker claim to prefix the next feedback
	deps        Deps
	repo        *git.Repo
	cache       *provider.Cache
	facts       *localFacts
	intent      *project.Intent
	model       *project.ModelSpec
	diag        *Diagnostic
	// ext is the external build executor of a fresh Build (nil: the native builder).
	ext *externalBuild
	// noEdit is the evidence for rounds that leave the candidate unchanged (noprogress.go).
	noEdit  noEditWatch
	unmoved unmovedWatch
	// env is the previous builder pass's environment failures (envfailure.go).
	env envMemory
	// invalid is the review that just ended without a valid verdict (review_retry.go).
	invalid *invalidReview
	// force is the tool the request being sent must call (RequestSpec.ForceTool), so that the
	// size measured for it is that of the request actually sent.
	force string
	// ledgerReset is the read_ledger_reset event of the reset that prepared the request being
	// sent, until Request logs it with the bytes its prefill appended.
	ledgerReset map[string]any
	// baselineRunning is the baseline check in progress, and baselineStop the record of the one
	// a stop interrupted (baseline.go). Neither is persisted.
	baselineRunning *baselineRunning
	baselineStop    map[string]any
}

// noRunNotice follows a refusal that happened before any run was created (stdout, indented
// like the refusal's detail lines).
const noRunNotice = "no newly created Build run; correct the named prerequisite before trying again"

// Build is `kogen intent build <slug>` (chapters 03-07): the start checks, then the builder
// conversation with the fixers and a verification pass after each round; a green pass goes
// to independent review and a verified, still identical candidate is committed. A Build has
// no time or token limit: it ends with a commit, an integrity stop, a provider failure,
// context exhaustion, an invalid or unresolved review, or an interrupt.
//
// The returned exit code is the command's. A refusal before any run exists is the
// *sys.Error to show (its lines end with the notice that no run was created); an interrupt
// is *sys.Interrupted. Once a run exists every other end, landed or not, is reported by
// Build itself on stdout and returns err nil (an unexpected internal failure is the only
// other error; the exit code is then 70).
func Build(ctx context.Context, s *sys.Session, in Input) (exit int, err error) {
	var b *Attempt
	err = buildRun(ctx, s, in, &b)
	exit, resultErr := conclude(s, &b, err)
	recordOutcome(in.Outcome, b, err)
	return exit, resultErr
}

// Resume is `kogen intent resume <build-id>`: it continues a stopped Build of this checkout
// from its checkpoint as a new run, after every custody check, or reports that the Build
// already landed. Returns and errors are those of Build.
func Resume(ctx context.Context, s *sys.Session, in ResumeInput) (exit int, err error) {
	var b *Attempt
	err = resumeRun(ctx, s, in, &b)
	exit, resultErr := conclude(s, &b, err)
	recordOutcome(in.Outcome, b, err)
	return exit, resultErr
}

// recordOutcome captures only the attempt owned by this invocation, never a run directory lookup.
func recordOutcome(out *Outcome, b *Attempt, err error) {
	if out == nil {
		return
	}
	out.Checks = []verify.CommandResult{}
	out.Error = nil
	errors.As(err, &out.Error)
	if b != nil && out.Error != nil {
		out.Error = b.stopError(out.Error)
	}
	if b == nil {
		return
	}
	if b.LastPass != nil {
		out.Checks = append(out.Checks, b.LastPass.Checks...)
	}
	out.Tree, _ = b.repo.Tree(b.Start, b.Excluded)
}

// conclude turns the end of a command into its exit code, reporting a stopped or
// interrupted Build.
func conclude(s *sys.Session, pb **Attempt, err error) (int, error) {
	b := *pb
	var interrupted *sys.Interrupted
	var refusal *sys.Error
	switch {
	case err == nil:
		return 0, nil
	case errors.As(err, &interrupted):
		if b != nil {
			if herr := b.interrupted(interrupted.Signal); herr != nil {
				return 70, herr
			}
		}
		return interrupted.ExitCode(), interrupted
	case errors.As(err, &refusal):
		if b == nil {
			refusal.Lines = append(refusal.Lines, noRunNotice)
			return refusal.Exit, refusal
		}
		exit, herr := b.stopped(refusal)
		if herr != nil {
			return 70, herr
		}
		return exit, nil
	}
	return 70, err
}

func buildRun(ctx context.Context, s *sys.Session, in Input, out **Attempt) error {
	agent.ApplyBuildReview(in.Deps.Client)
	if in.Context != nil {
		if err := in.Context.Validate(); err != nil {
			return err
		}
	}
	repo, err := git.Open(in.Project, s.Env)
	if err != nil {
		return err
	}
	root := repo.Dir
	cfg, err := project.LoadConfig(root)
	if err != nil {
		return err
	}
	start := repo.Head()
	if start == "" {
		return sys.Fail("environment", "no_head", root+" has no commits; run kogen init", 3)
	}
	op, err := repo.OperationInProgress()
	if err != nil {
		return err
	}
	if op != "" {
		return sys.Fail("environment", "git_operation_in_progress", "a "+op+" is in progress; finish or abort it first", 3)
	}
	lock, err := git.AcquireBuild(root, s)
	if err != nil {
		return err
	}
	defer lock.Release()
	if repo.Head() != start {
		return sys.Fail("intent", "changed_since_approval", "HEAD changed while starting Build; review with kogen intent approve "+in.Slug, 1)
	}
	return checked(ctx, s, in, repo, cfg, start, out)
}

// cleanPaths is the Git rule of a Build (GIT-1): only this Intent's folder and acceptance
// files, and other Intents' own folders, may be uncommitted; other Intents stay out of the
// candidate and the commit (VER-10). It returns the folders to exclude.
func cleanPaths(repo *git.Repo, intent *project.Intent) ([]string, error) {
	changed, err := repo.ChangedPaths()
	if err != nil {
		return nil, err
	}
	own := project.IntentDir(intent.Slug) + "/"
	var other, dirty []string
	for _, p := range changed {
		if strings.HasPrefix(p, ".kogen/intents/") && !strings.HasPrefix(p, own) {
			other = append(other, p)
		}
	}
	for _, p := range changed {
		if !slices.Contains(other, p) && !slices.Contains(intent.Acceptance, p) && !strings.HasPrefix(p, own) {
			dirty = append(dirty, p)
		}
	}
	if len(dirty) > 0 {
		e := sys.Fail("environment", "dirty_tree",
			fmt.Sprintf("%d changed path(s) are not part of an Intent; commit, stash or discard them first", len(dirty)), 5)
		e.Lines = dirty[:min(20, len(dirty))]
		return nil, e
	}
	var excluded []string
	for _, p := range other {
		parts := strings.Split(p, "/")
		dir := strings.Join(parts[:min(3, len(parts))], "/")
		if !slices.Contains(excluded, dir) {
			excluded = append(excluded, dir)
		}
	}
	return excluded, nil
}

// buildRoles are the provider roles a Build signs in with: the review's, and the builder's
// unless an external executor serves it (it uses its own sign-in, never a Kogen provider's).
func buildRoles(cfg *project.Config) []provider.Role {
	var roles []provider.Role
	if role := cfg.Models["build"]; !role.External() {
		roles = append(roles, core.ProviderRole(role))
	}
	if role := cfg.Models["review"]; !role.External() {
		roles = append(roles, core.ProviderRole(role))
	}
	return roles
}

func checked(ctx context.Context, s *sys.Session, in Input, repo *git.Repo, cfg *project.Config, start string, out **Attempt) error {
	root, slug := repo.Dir, in.Slug
	if err := project.RequireIntentDir(root, slug); err != nil {
		return err
	}
	approval, err := project.ReadApproval(root, slug)
	if err != nil {
		return err
	}
	if approval == nil {
		return sys.Fail("intent", "not_approved", slug+" is not approved; review it with kogen intent approve "+slug, 5)
	}
	if approval.Base == "" || approval.Base != start {
		return sys.Fail("intent", "changed_since_approval", fmt.Sprintf("approval base: %s; current base: %s; review with kogen intent approve %s", approval.Base, start, slug), 1)
	}
	baseline, err := project.Baseline(root, slug, cfg)
	if err != nil {
		return err
	}
	if sha := project.Hash(root, baseline); sha != approval.SHA256 {
		return sys.Fail("intent", "changed_since_approval",
			fmt.Sprintf("%s changed after approval and is now %s; review it again with kogen intent approve %s", slug, short(sha), slug), 1)
	}
	source := project.SourceRefFromMap(approval.SourceProvenance)
	if err := project.ValidateSource(source); err != nil {
		return err
	}
	intent, err := project.LoadIntent(root, slug)
	if err != nil {
		return err
	}
	excluded, err := cleanPaths(repo, intent)
	if err != nil {
		return err
	}
	if !repo.CanCommit() {
		return sys.Fail("environment", "git_identity_missing", "no Git identity for the commit; run git config user.name \"<name>\" and git config user.email \"<email>\" (global or repository) before building", 3)
	}
	if intent.Model == nil {
		return sys.Fail("intent", "parse", "the Intent's Model: line cannot be read", 1)
	}
	stages, err := project.ParseStages(intent.Text)
	if err != nil {
		return sys.Fail("intent", "lint", err.Error(), 1)
	}
	plan := stageDefs(stages)
	ext, err := selectExecutor(in.Deps, cfg.Models["build"])
	if err != nil {
		return err
	}
	reviewer, err := selectReviewer(in.Deps, cfg.Models["review"])
	if err != nil {
		return err
	}
	if reviewer != nil {
		in.Deps.Reviewer = reviewer
	}
	if err := provider.RequireLogin(s.Getenv("HOME"), buildRoles(cfg)); err != nil {
		return err
	}
	if err := verify.RequireTools(s, in.Tools, root, cfg, false); err != nil {
		return err
	}
	if !intent.Model.None {
		if err := in.Tools.Require(); err != nil {
			return err
		}
	}
	run, err := StartRun(root)
	if err != nil {
		return err
	}
	facts, err := startFacts(root, slug, run, cfg, "", "")
	if err != nil {
		return err
	}
	if in.Context != nil {
		if err := in.Context.capture(run); err != nil {
			return err
		}
	}
	// GIT-8: a Build that does not commit leaves the index as it found it.
	gitIndex, err := repo.IndexPath()
	if err != nil {
		return err
	}
	if err := repo.SaveIndex(filepath.Join(run.Dir, "index-at-start")); err != nil {
		return err
	}
	digests := map[string]string{}
	for _, p := range baseline {
		digests[p] = fileDigest(root, p)
	}
	startTree, err := repo.Tree(start, excluded)
	if err != nil {
		return err
	}
	approvalFile, err := os.ReadFile(project.ApprovalPath(root, slug))
	if err != nil {
		return err
	}
	b := &Attempt{
		State: State{
			Root: root, Slug: slug, Config: cfg, IntentText: intent.Text, Start: start, Baseline: baseline,
			BaselineDigests: digests, Excluded: core.NonNil(excluded), Run: run, GitIndex: gitIndex, StartTree: startTree,
			Phase: "startup", T0: time.Now().UnixMilli(), Continuation: Continuation{Stage: StageStartup},
			ApprovalBytes: encodeBase64(approvalFile), WorkingContext: map[string]*OwnerContext{},
			SourceProvenance: source, PromptCache: map[string]provider.CacheState{},
			Usage: core.ZeroTokens(), AttemptUsage: core.ZeroTokens(), CacheIDs: map[string]string{},
			StagePlan: plan, StageProgress: initialProgress(plan),
		},
		s: s, deps: in.Deps, repo: repo, cache: provider.NewCache(nil), facts: facts, intent: intent, model: intent.Model, diag: in.Context, ext: ext,
	}
	if ext == nil && in.BuildRequestBudget > 0 {
		b.BuildRequestBudget = &RequestBudget{Limit: in.BuildRequestBudget}
	}
	*out = b
	run.Event(map[string]any{"event": "start", "slug": slug, "start_head": start, "approved": approval.SHA256})
	run.Event(agent.BudgetEvent(in.Deps.Client))
	if err := b.Save(b.Continuation); err != nil {
		return err
	}
	return b.begin(ctx)
}

// begin is a fresh Build's start checks (AUT-3..5) and then the builder.
func (b *Attempt) begin(ctx context.Context) error {
	if err := b.repo.CheckCommitMsg(b.s, b.intent.Title, b.Slug); err != nil {
		return err
	}
	if err := b.BaselineIntact(); err != nil {
		return err
	}
	ready := b.readiness()
	if err := ready.Setup(ctx, b.s, b.Root, false); err != nil {
		return err
	}
	if err := verify.RequireTools(b.s, b.deps.Tools, b.Root, b.Config, true); err != nil {
		return err
	}
	if err := b.BaselineIntact(); err != nil {
		return err
	}
	if err := b.recordBaseline(ctx); err != nil {
		return err
	}
	b.s.Puts("building " + b.Slug)
	if err := b.facts.update(b, "building", ""); err != nil {
		return err
	}
	b.Phase = "building"
	if err := b.Track(); err != nil {
		return err
	}
	brief, err := b.brief()
	if err != nil {
		return err
	}
	sess, err := b.startBuilder(ctx, brief)
	if err != nil {
		return err
	}
	defer sess.Close()
	return b.drive(ctx, sess, executor.Input{}, true)
}

func (b *Attempt) readiness() *verify.Readiness {
	return &verify.Readiness{Root: b.Root, Repo: b.repo, Config: b.Config, Tools: b.deps.Tools, Log: b.Run}
}

// ---- state, facts and checkpoints ----

// Track publishes the local facts of the Build's current state.
func (b *Attempt) Track() error { return b.facts.update(b, "", "") }

// Save makes c the continuation and publishes a complete checkpoint: the state together
// with the identity of the checkout, the candidate tree, the user's index and the
// approval, by atomic rename (0600).
func (b *Attempt) Save(c Continuation) error {
	b.Continuation = c
	b.PromptCache = b.cache.States()
	if err := b.Track(); err != nil {
		return err
	}
	candidate, err := b.repo.Tree(b.Start, nil)
	if err != nil {
		return err
	}
	index, err := os.ReadFile(b.GitIndex)
	if err != nil {
		return err
	}
	identity, err := fileIdentity(b.Root)
	if err != nil {
		return err
	}
	state, err := core.EncodeJSON(b.State)
	if err != nil {
		return err
	}
	if err := b.Run.TakeLogErr(); err != nil {
		return err
	}
	doc := Checkpoint{
		Version: 4, Identity: identity, Candidate: candidate, Index: encodeBase64(index),
		Approval: b.ApprovalBytes, State: state, StageProgress: b.StageProgress,
	}
	if b.Blocker != nil {
		if doc.RecoveryRaw, err = rawIdentity(b.repo, b.Root, b.StartTree); err != nil {
			return err
		}
	}
	return b.Run.PublishCheckpoint(doc)
}

// BaselineIntact is the baseline guard (VER-8): after every shell call, fixer and pass the
// baseline must be as approved, the same files (a new file in the Intent's folder or
// matching `protect` joins it) with the same bytes.
func (b *Attempt) BaselineIntact() error {
	if err := b.validateStages(); err != nil {
		return err
	}
	if err := b.validateWorkingContext(); err != nil {
		return err
	}
	if err := project.ValidateSource(b.SourceProvenance); err != nil {
		return err
	}
	now, err := project.Baseline(b.Root, b.Slug, b.Config)
	if err != nil {
		return err
	}
	var changed []string
	for _, p := range b.Baseline {
		if fileDigest(b.Root, p) != b.BaselineDigests[p] {
			changed = append(changed, p)
		}
	}
	for _, p := range now {
		if !slices.Contains(b.Baseline, p) {
			changed = append(changed, p)
		}
	}
	if len(changed) > 0 {
		return sys.Fail("candidate", "baseline_changed", "the Build changed acceptance files: "+strings.Join(changed, ", ")+
			"; nothing was committed; review the files, then approve again or discard the edits", 1)
	}
	return nil
}

func (b *Attempt) headIntact() error {
	head := b.repo.Head()
	if head == b.Start {
		return nil
	}
	current := "(missing)"
	if head != "" {
		current = short(head)
	}
	return sys.Fail("candidate", "head_moved",
		fmt.Sprintf("HEAD moved from %s to %s during the Build; nothing was committed", short(b.Start), current), 1)
}

// attempts is the provider's observer: each transport attempt goes to the run log.
type attempts struct{ run *Run }

func (a attempts) Attempt(record map[string]any) {
	a.run.Event(map[string]any{"event": "provider_attempt", "provider": record})
}

// Request sends one request of a conversation and returns the response and the input that
// was sent (reduced to a local working window when the request outgrew its budget). It
// validates custody first, checkpoints before and after, and keeps the Build's usage,
// model time and unknown-request count, the provider attempt records and the image
// delivery events (LOOP-10, GPT-9).
func (b *Attempt) Request(ctx context.Context, sp RequestSpec) (*provider.Response, []any, error) {
	if err := b.s.Err(); err != nil {
		return nil, nil, err
	}
	if err := b.validateStages(); err != nil {
		return nil, nil, err
	}
	if err := b.validateWorkingContext(); err != nil {
		return nil, nil, err
	}
	if err := project.ValidateSource(b.SourceProvenance); err != nil {
		return nil, nil, err
	}
	budget := b.BuildRequestBudget
	if sp.Owner != "build" {
		budget = nil
	}
	if budget != nil && budget.Count >= budget.Limit {
		b.Run.Event(map[string]any{"event": "build_request_budget", "role": "build", "count": budget.Count, "limit": budget.Limit})
		return nil, nil, sys.Fail("candidate", "build_request_budget", fmt.Sprintf(
			"the Build has used its budget of %d builder requests (%d sent); the candidate, checkpoint and approval are preserved and nothing was committed",
			budget.Limit, budget.Count), 1)
	}
	b.force = sp.ForceTool
	defer func() { b.force = "" }()
	b.ledgerReset = nil
	input, err := b.prepareContext(sp.Owner, sp.Role, sp.Instructions, sp.Input, sp.Tools)
	if err != nil {
		return nil, nil, err
	}
	reopened := len(input)
	if sp.Prefill != nil {
		if input, err = sp.Prefill(input); err != nil {
			return nil, nil, err
		}
	}
	if b.ledgerReset != nil {
		b.ledgerReset["prefilled_bytes"] = contentBytes(input[reopened:])
		b.Run.Event(b.ledgerReset)
		b.ledgerReset = nil
	}
	cont := b.Continuation
	switch {
	case sp.Retain != nil:
		sp.Retain(&cont, input)
	case sp.Owner == "build":
		cont.Input = input
	}
	if err := b.Save(cont); err != nil {
		return nil, nil, err
	}
	t0 := time.Now()
	b.s.Progress(fmt.Sprintf("kogen: %s request %s/%s", sp.Owner, sp.Role.Model, sp.Role.Effort))
	b.UnknownRequests++
	if budget != nil {
		budget.Count++
	}
	if err := b.Save(b.Continuation); err != nil {
		return nil, nil, err
	}
	var parent any
	if b.RootRun != nil {
		parent = *b.RootRun
	}
	req := provider.Request{
		Role: core.ProviderRole(sp.Role), Instructions: sp.Instructions, Input: input, Tools: sp.Tools, ToolChoice: sp.ForceTool, CacheID: b.cacheID(sp.Owner), Cache: b.cache,
		Context: map[string]any{
			"phase": sp.Owner, "role": sp.Owner, "run_id": b.Run.ID, "slug": b.Slug, "lineage": parent,
			"pass": b.Pass, "repair": b.Repairs,
		},
	}
	requestBytes := b.requestBytes(req)
	resp, err := tools.Deliver(input, sp.Owner, b.Run.Event, func() (*provider.Response, error) {
		resp, err := b.deps.Client.Respond(ctx, b.s, req, attempts{b.Run})
		return resp, agent.NameBudgetExpiry(err, b.deps.Client.ResponseBudget)
	})
	if err != nil {
		return nil, nil, err
	}
	wall := time.Since(t0).Milliseconds()
	b.UnknownRequests--
	b.ModelActiveMS += wall
	got := core.ResponseTokens(sp.Role, resp)
	b.AttemptUsage = b.AttemptUsage.Plus(got)
	b.Usage = b.Usage.Plus(got)
	if err := b.Save(Continuation{Stage: StageTool, Owner: sp.Owner, Response: resp.Items, Request: true}); err != nil {
		return nil, nil, err
	}
	b.s.Progress(fmt.Sprintf("kogen: %s response %s wall_ms=%d", sp.Owner, got.Line(), wall))
	event := map[string]any{
		"event": "request", "operation_id": resp.OperationID, "role": sp.Owner, "model": sp.Role.Model,
		"effort": sp.Role.Effort, "usage": requestUsageOf(got, resp), "wall_ms": wall, "request_bytes": requestBytes,
	}
	if sp.Owner == "review" {
		event["review_round"] = b.Review
	} else {
		event["build_round"] = b.Round
	}
	if sp.Owner == "build" {
		event["items"] = nil
		response := make([]any, len(resp.Items))
		for i, it := range resp.Items {
			response[i] = it
		}
		event["response_id"] = resp.ID
		event["response_items"] = b.Run.recordItems(response)
	}
	b.Run.Event(event)
	return resp, input, nil
}

// Verify runs one verification pass over the current candidate (VER-1..10): numbered from 1
// in this Build, recorded in the run log and as b.LastPass. The fixers belong to the end of a
// builder round, not to a pass.
func (b *Attempt) Verify(ctx context.Context) (verify.Pass, error) {
	if err := b.promoteModel(); err != nil {
		return verify.Pass{}, err
	}
	models, err := maintainedModels(b.Root)
	if err != nil {
		return verify.Pass{}, err
	}
	b.Pass++
	if err := b.Track(); err != nil {
		return verify.Pass{}, err
	}
	if err := b.facts.update(b, "verifying", ""); err != nil {
		return verify.Pass{}, err
	}
	in := b.verifyInput(b.Pass)
	in.MaintainedModels = models
	pass, err := b.verifyReusing(ctx, in)
	if err != nil {
		return verify.Pass{}, err
	}
	b.LastPass = &pass
	return pass, b.Track()
}

func (b *Attempt) verifyInput(n int) verify.Input {
	return verify.Input{
		Root: b.Root, Repo: b.repo, Config: b.Config, Intent: b.intent, Start: b.Start, Excluded: b.Excluded,
		N: n, RunDir: b.Run.Dir, Tools: b.deps.Tools, Log: b.Run, Intact: b.BaselineIntact,
	}
}

// PassFeedback is what goes back to the repair owner after a red pass; completion names the
// tool the owner calls when done ("finish", "submit_review").
func (b *Attempt) PassFeedback(pass verify.Pass, completion string) string {
	acceptance := ""
	if b.Config.Acceptance != nil {
		acceptance = b.Config.Acceptance.Run
	}
	return pass.Feedback(acceptance, completion)
}

func (b *Attempt) elapsed() time.Duration { return time.Since(time.UnixMilli(b.T0)) }

files.build/executor_native.go:
package build

import (
	"context"
	"encoding/json"
	"errors"
	"slices"
	"strings"
	"time"

	"github.com/KogenAI/kogen-coordinator/project"
	"github.com/KogenAI/kogen-executor/agent"
	"github.com/KogenAI/kogen-executor/core"
	"github.com/KogenAI/kogen-executor/executor"
	"github.com/KogenAI/kogen-loop/api"
	"github.com/KogenAI/kogen-loop/loop"
	"github.com/KogenAI/kogen-loop/provider"
	"github.com/KogenAI/kogen-loop/sys"
	"github.com/KogenAI/kogen-loop/tools"
)

// The builder's tools: the file and command tools plus the two terminal tools.
var (
	builderTools = []string{"shell", "read_file", "view_image", "write_file"}
	builderDefs  = []string{"shell", "read_file", "view_image", "write_file", "finish", "report_blocker"}
)

// builderDefinitions are the builder's tool definitions, the shell's with the executing tool's
// own policy: the generic tools of builderTools, then finish and report_blocker.
func builderDefinitions(tl *tools.Tools) []any {
	return slices.Concat(core.ShellDefinitions(tl, builderTools), agent.AsAny(BuilderToolDefinitions(FinishTool, ReportBlockerTool)))
}

// nativeExecutor is the default build executor (docs/executor-contract.md): Kogen's own
// builder round, run by kogen-loop's engine with hooks that keep every checkpoint, run-log
// event and custody check of the Build in the order the builder always had them. It works on
// the Build it belongs to, so Start takes only the brief, the deadline and nothing else from
// the Task; the checkout, the baseline and the role are the Attempt's.
type nativeExecutor struct {
	b *Attempt
	// tail are the messages that follow the opening message (the caller's diagnostic data).
	tail []any
}

// nativeVersion identifies the engine the native builder runs on.
const nativeVersion = "kogen-loop " + api.Library

func (nativeExecutor) Describe() executor.Descriptor {
	return executor.Descriptor{
		Name:     executor.Native,
		Contract: executor.Contract,
		Version:  nativeVersion,
		Capabilities: executor.Capabilities{
			Roles:        []string{executor.RoleBuild},
			Resume:       executor.ResumeExact,
			Continuation: true,
			Usage:        executor.UsageProvider,
			Prevention:   []string{executor.PreventWriteTool},
			Blocker:      true,
			Images:       true,
			MaxRounds:    0,
		},
	}
}

// Start opens the native conversation with the brief as the opening message, byte for byte
// the message the builder has always opened with.
func (n nativeExecutor) Start(_ context.Context, t executor.Task, _ executor.Sink) (executor.Session, error) {
	opening := map[string]any{"role": "user", "content": provider.ContractBlocks(t.Brief.Stable, t.Brief.Dynamic)}
	s := n.b.nativeSession(append([]any{opening}, n.tail...), nil, nil)
	s.deadline = t.Deadline
	return s, nil
}

// nativeSession is the builder's conversation across rounds.
type nativeSession struct {
	b *Attempt
	// pending is the exact input of the next round when it has no feedback: the opening
	// message of a fresh Build, or the saved input of a resumed builder stage.
	pending []any
	// input and finish are the conversation after the last round and the finish call that
	// ended it (nil after an answer without a tool call); feedback answers it.
	input  []any
	finish map[string]any
	// deadline bounds a round (zero: none).
	deadline time.Time
}

func (b *Attempt) nativeSession(pending, input []any, finish map[string]any) *nativeSession {
	return &nativeSession{b: b, pending: pending, input: input, finish: finish}
}

func (n *nativeSession) Handle() executor.Handle {
	return executor.Handle{Executor: executor.Native, Version: nativeVersion, SessionID: n.b.Run.ID, Resume: executor.ResumeExact}
}

func (n *nativeSession) Close() error { return nil }

// attemptRequester sends the builder's requests through the Build's own bookkeeping
// (Attempt.Request): custody checks, working context, checkpoints, usage and image delivery.
type attemptRequester struct {
	b    *Attempt
	role project.Role
}

func (r attemptRequester) Request(ctx context.Context, q loop.Request) (*provider.Response, []any, error) {
	return r.b.Request(ctx, RequestSpec{Owner: q.Owner, Role: r.role, Instructions: q.Instructions, Input: q.Input, Tools: q.Tools})
}

// Round runs one builder round: the builder's requests and the tool calls it asks for, until
// it finishes or answers without a tool call. The round's end is the builder's claim; the
// fixers, verification and review are the Build's (drive).
func (n *nativeSession) Round(ctx context.Context, in executor.Input) (executor.RoundResult, error) {
	b := n.b
	var input []any
	if in.Feedback == "" && n.pending != nil {
		input, n.pending = n.pending, nil
	} else {
		input = b.afterRound(n.input, n.finish, in.Feedback)
	}
	if !n.deadline.IsZero() {
		var cancel context.CancelFunc
		ctx, cancel = context.WithDeadline(ctx, n.deadline)
		defer cancel()
	}
	role := b.Config.Models["build"]
	tl := &tools.Tools{Root: b.Root, Session: b.s, Repo: agent.Git(b.repo), Enabled: builderTools, Protected: b.Baseline, Excluded: b.Excluded, ShellAfter: b.deps.shellAfter}
	rd := loop.Round{
		Owner: "build", Role: core.ProviderRole(role), Instructions: BuilderInstructions(),
		Definitions: builderDefinitions(tl),
		Tools:       tl,
		Terminal:    []string{FinishTool},
	}
	var base []any // the round's input after replay, as the stage validation sees it
	var usages []api.Usage
	hooks := loop.Hooks{
		BeforeRequest: func(ctx context.Context, input []any) error {
			if err := b.facts.update(b, "building", ""); err != nil {
				return err
			}
			return b.Save(Continuation{Stage: StageBuilder, Input: input})
		},
		AfterResponse: func(ctx context.Context, resp *provider.Response, sent []any) error {
			if err := b.Track(); err != nil {
				return err
			}
			base = slices.Concat(sent, tools.Replay(resp.Items))
			usages = append(usages, loop.UsageOf(resp))
			return nil
		},
		BeforeCall: func(ctx context.Context, call tools.Call, input []any) error {
			if err := b.s.Err(); err != nil {
				return err
			}
			if err := b.validateStagesAs(Continuation{Stage: StageBuilder, Input: base}); err != nil {
				return err
			}
			if err := b.validateWorkingContext(); err != nil {
				return err
			}
			if err := project.ValidateSource(b.SourceProvenance); err != nil {
				return err
			}
			return b.Save(Continuation{Stage: StageTool, Owner: "build", Input: input})
		},
		HandleCall: func(ctx context.Context, call tools.Call) (loop.Handled, error) {
			if call.Name != ReportBlockerTool {
				return loop.Handled{}, nil
			}
			text, err := b.reportBlocker(call.Args(), call)
			if err != nil {
				return loop.Handled{}, err
			}
			return loop.Handled{Handled: true, Output: tools.Output{Text: text}}, nil
		},
		AfterCall: func(ctx context.Context, call tools.Call, out tools.Output, terminal bool, input []any) error {
			if call.Name == "write_file" {
				b.noEdit.wrote = true
			}
			if !terminal {
				path, _ := call.Args()["path"].(string)
				failed := strings.HasPrefix(out.Text, "error:") || strings.HasPrefix(out.Text, "refused:")
				if call.Name == "shell" {
					if strings.HasPrefix(out.Text, "exit status: ") {
						failed = !strings.HasPrefix(out.Text, "exit status: 0\n")
					} else {
						var envelope struct {
							Status     string `json:"status"`
							ExitStatus int    `json:"exit_status"`
						}
						if json.Unmarshal([]byte(out.Text), &envelope) == nil && envelope.Status == "completed" {
							failed = envelope.ExitStatus != 0
						}
					}
				}
				b.toolProgress(call.Name, path, failed)
				if event := tools.ReadEvent(call, out, "build"); event != nil {
					b.Run.Event(event)
				}
			}
			var resultLog any = b.Run.recordBlob("finish")
			if !terminal {
				resultLog = provider.Fingerprint(out.Value())
			}
			event := map[string]any{
				"event": "tool_call", "call_id": call.CallID(), "name": call.Name,
				"arguments": b.Run.recordBlob(call.Arguments), "result": resultLog,
			}
			if !terminal {
				for k, v := range b.toolRecordFields(call, out, func(string) (int, bool) { return 0, false }) {
					event[k] = v
				}
			}
			b.Run.Event(event)
			done := &Completed{Call: call.Item, Result: "finish"}
			if !terminal {
				done.Result = out.Value()
			}
			if err := b.Save(Continuation{Stage: StageTool, Owner: "build", Input: input, Completed: done}); err != nil {
				return err
			}
			if call.Name == "shell" {
				return b.BaselineIntact()
			}
			return nil
		},
	}
	res, err := loop.Run(ctx, rd, input, attemptRequester{b, role}, hooks)
	if err != nil {
		return executor.RoundResult{}, n.stop(ctx, err)
	}
	n.input, n.finish = res.Input, nil
	if res.Terminal != nil {
		n.finish = res.Terminal.Item
	}
	if err := b.Save(Continuation{Stage: StageBuilderVerify, Input: n.input, Finish: n.finish}); err != nil {
		return executor.RoundResult{}, err
	}
	out := executor.RoundResult{Ending: executor.EndNoCall, Usage: executorUsage(loop.SumUsage(usages...), res.Response), Handle: n.Handle()}
	claim := finalText(res.Response)
	if res.Terminal != nil {
		out.Ending = executor.EndFinish
		claim = res.Terminal.Arguments
		if summary, ok := res.Terminal.Args()["summary"].(string); ok {
			claim = summary
		}
	}
	out.Claim = tools.Cut(claim)
	return out, nil
}

// stop is the error a round ends with. A cancelled round is an interrupt or the deadline
// (a sys.Interrupted, and the Session's own interrupt, keep their exit codes); every other
// stop (a custody stop, a builder-reported blocker, a provider failure) is returned unchanged.
func (n *nativeSession) stop(ctx context.Context, err error) error {
	var interrupted *sys.Interrupted
	if errors.As(err, &interrupted) || ctx.Err() == nil {
		return err
	}
	var typed *sys.Error
	if errors.As(err, &typed) && typed.Class == "candidate" {
		return err
	}
	if ie := n.b.s.Err(); ie != nil {
		return ie
	}
	if errors.Is(ctx.Err(), context.DeadlineExceeded) {
		return executor.Fail(executor.ReasonDeadline, "the round deadline passed; the builder's commands were stopped")
	}
	return executor.Fail(executor.ReasonInterrupted, "the round was interrupted; the builder's commands were stopped")
}

// executorUsage is a round's provider-reported usage as the executor contract states it.
func executorUsage(u api.Usage, last *provider.Response) executor.Usage {
	out := executor.Usage{Input: u.Input, Cached: u.Cached, Output: u.Output, Reasoning: u.Reasoning, State: u.State, Source: executor.UsageProvider}
	if last != nil {
		out.Model = last.Model
	}
	return out
}

// finalText is the text of the answers in a response (the claim of a round that ended
// without a tool call).
func finalText(resp *provider.Response) string {
	if resp == nil {
		return ""
	}
	var text string
	for _, it := range resp.Items {
		if it["type"] != "message" {
			continue
		}
		content, _ := it["content"].([]any)
		for _, c := range content {
			if part, ok := c.(map[string]any); ok && part["type"] == "output_text" {
				if t, ok := part["text"].(string); ok {
					if text != "" {
						text += "\n"
					}
					text += t
				}
			}
		}
	}
	return text
}

